53	  /// Generates/updates required files and project settings for Darwin
54	  /// Dependency Managers (CocoaPods and Swift Package Manager). Projects may
55	  /// use only CocoaPods (if no SPM compatible dependencies or SPM has been
56	  /// disabled), only Swift Package Manager (if no CocoaPod dependencies), or
57	  /// both. This only generates files for the manager(s) being used.
58	  ///
59	  /// CocoaPods requires a Podfile and certain values in the Flutter xcconfig
60	  /// files.
61	  ///
62	  /// Swift Package Manager requires a generated Package.swift and certain
63	  /// settings in the Xcode project's project.pbxproj and xcscheme (done later
64	  /// before build).
65	  Future<void> setUp({required FlutterDarwinPlatform platform}) async {
66	    final XcodeBasedProject xcodeProject = platform.xcodeProject(_project);
67	    if (xcodeProject.usesSwiftPackageManager) {
68	      await _swiftPackageManager.generatePluginsSwiftPackage(_plugins, platform, xcodeProject);
69	    } else if (xcodeProject.flutterPluginSwiftPackageInProjectSettings) {
70	      // If Swift Package Manager is not enabled but the project is already
71	      // integrated for Swift Package Manager, pass no plugins to the generator.
72	      // This will still generate the required Package.swift, but it will have
73	      // no dependencies.
74	      await _swiftPackageManager.generatePluginsSwiftPackage(
75	        <Plugin>[],
76	        platform,
77	        xcodeProject,
78	        flutterAsADependency: false,
79	      );
80	    }
81	
82	    // Skip updating Podfile if project is a module, since it will use a
83	    // different module-specific Podfile.
84	    if (_project.isModule) {
85	      return;
86	    }
87	    final (
88	      :int totalCount,
89	      :int swiftPackageCount,
90	      :int podCount,
91	    ) = await _evaluatePluginsAndPrintWarnings(
92	      platform: platform,
93	      xcodeProject: xcodeProject,
94	      hostPlatformIsMacOS: _hostPlatform.isMacOS,
95	    );
96	
97	    final bool useCocoapods;
98	    if (xcodeProject.usesSwiftPackageManager) {
99	      useCocoapods = swiftPackageCount < totalCount;
100	    } else {
101	      // When Swift Package Manager is not enabled, set up Podfile if plugins
102	      // is not empty, regardless of if plugins are CocoaPod compatible. This
103	      // is done because `processPodsIfNeeded` uses `hasPlugins` to determine
104	      // whether to run.
105	      useCocoapods = _plugins.isNotEmpty;
106	    }
107	
108	    if (useCocoapods) {
109	      await _cocoapods.setupPodfile(xcodeProject);
110	    }
111	    /// The user may have a custom maintained Podfile that they're running `pod install`
112	    /// on themselves.
113	    else if (xcodeProject.podfile.existsSync() && xcodeProject.podfileLock.existsSync()) {
114	      _cocoapods.addPodsDependencyToFlutterXcconfig(xcodeProject);
115	    }
116	
117	    final event = Event.flutterInjectDarwinPlugins(
118	      platform: platform.name,
119	      isModule: _project.isModule,
120	      swiftPackageManagerUsable: xcodeProject.usesSwiftPackageManager,
121	      swiftPackageManagerFeatureEnabled: _featureFlags.isSwiftPackageManagerEnabled,
122	      // TODO(matanlurey): Remove from unified_analytics and then remove this key.
123	      projectDisabledSwiftPackageManager: !_featureFlags.isSwiftPackageManagerEnabled,
124	      projectHasSwiftPackageManagerIntegration:
125	          xcodeProject.flutterPluginSwiftPackageInProjectSettings,
126	      pluginCount: totalCount,
127	      swiftPackageCount: swiftPackageCount,
128	      podCount: podCount,
129	    );
130	
131	    _analytics.send(event);
132	  }
